    'special_txt',
    'name_txt',
    'gunPoints_txt',
    'bubblePoints_txt',
  ]);
  expect(layout.popup.bounds.width).toBeCloseTo(145, 2);
  expect(layout.popup.bounds.height).toBeCloseTo(62, 2);
});

